"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["50532"],{77121(e){e.exports=JSON.parse('{"id":"FIN-1310","slug":"systemically-important-bank","term":"Systemically Important Bank","also_known_as":[],"difficulty":"Advanced","definition":"A systemically important bank is a bank whose size, complexity, interconnectedness or importance to the financial system is such that its failure could cause serious damage to the wider economy.","explanation":["After the 2008 financial crisis, regulators recognised that some banks were too big to fail, so governments felt compelled to rescue them. To reduce this problem, regulators identify systemically important banks and apply stricter rules to them.","At the global level, the Financial Stability Board publishes an annual list of global systemically important banks, often called G-SIBs, based on factors such as size, cross-border activity, interconnectedness, complexity and how hard they would be to replace. National regulators also identify domestic systemically important banks.","These banks must hold additional capital buffers, meet stricter requirements on loss-absorbing debt, undergo more intense supervision and stress testing, and prepare detailed plans for how they could be resolved without taxpayer support.","For example, a large global bank operating in dozens of countries, with trillions of dollars in assets and deep links to other financial institutions, would be designated as a G-SIB and required to hold extra capital above standard minimums. The aim is to reduce both the likelihood and the impact of failure."],"note":"","total":1500,"prev":{"slug":"systematic-risk","term":"Systematic Risk"},"next":{"slug":"t-account","term":"T-Account"}}')}}]);